def divisor(n):
    count = 1  # Start with 1
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            count += 1
            # If i is the square root of n, add 1 (not both i and i as in the original code)
            if i == (n // i):
                count += 1
                break
    return count
``

