def convert_list_dictionary(keys, values, scores):
    # Ensure the length of the input lists is the same
    if len(keys) != len(values) or len(keys) != scores:
        raise ValueError("Input lists must have the same length")

    # Create the nested dictionary
    nested_dict = {}
    for key, value, score in zip(keys, values, scores):
        nested_dict.setdefault(key, {})[value] = score

    # Return the nested dictionary with all the values
    return nested_dict

