from collections import Counter

def count_bidirectional(tuples):
    # Create a counter from the tuples for easy counting
    counter = Counter(tuples)
    bidirectional_pairs = 0

    # Iterate over the tuples and count bidirectional pairs
    for tuple1 in counter.keys():
        # Get the reverse of the tuple
        reversed_tuple = (tuple1[1], tuple1[0])
        bidirectional_pairs += counter[tuple1] * (counter[tuple1] - 1) / 2 + 1
        bidirectional_pairs += counter[tuple1] * (counter[reversed_tuple] - 1) / 2 + 1

    return bidirectional_pairs
