    dp = [[0] * n for _ in range(n)]

    # Initialize the dp array with the values from the original array
    for i in range(n):
        dp[i][i] = nums[i]

    # Calculate the maximum product for subarrays of length 2 to n
    for length in range(2, n + 1):
        for j in range(n - length + 1):
